            pbid = 0.0
        prev_bids.append(float(pbid))
        urgency = 0
        if opp.get('hp', 10) <= 3:
            urgency += 2
        elif opp.get('hp', 10) <= 5:
            urgency += 1
        if opp.get('no_water_days', 0) >= 2:
            urgency += 2
        elif opp.get('no_water_days', 0) >= 1:
            urgency += 1
        opp_infos.append({
            'id': oid,
            'bid': float(pbid),
            'budget': float(opp.get('budget', 0.0)),
            'urgency': urgency,
            'salary': float(opp.get('daily_salary', 0.0))
        })

    opp_infos.sort(key=lambda x: (x['bid'] + 8 * x['urgency'], x['budget']), reverse=True)

    highest_prev = max(prev_bids) if prev_bids else 0.0
