def get_bid(day_context, my_status, opponents_status):
    MY_WATER_REQUIREMENT = 8
    MY_DAILY_SALARY = 140
    MAX_HP = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_agents = len(alive_opponents) + 1 

    if not alive_opponents:
        return min(my_status['budget'], MY_DAILY_SALARY * 0.1)

    base_bid = MY_DAILY_SALARY * 0.5

    if my_status['hp'] <= 2:
        base_bid = MY_DAILY_SALARY * 0.95
    elif my_status['no_water_days'] > 0:
        base_bid = MY_DAILY_SALARY * 0.8
    elif my_status['hp'] < MAX_HP / 2:
        base_bid = MY_DAILY_SALARY * 0.7

    supply_per_agent = day_context['supply'] / num_alive_agents
    if supply_per_agent < MY_WATER_REQUIREMENT:
        base_bid = max(base_bid, MY_DAILY_SALARY * 0.75)
        if my_status['hp'] <= 4:
            base_bid = MY_DAILY_SALARY * 0.98

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    final_bid = base_bid

    if highest_prev_bid > MY_DAILY_SALARY * 0.8:
        if my_status['hp'] > 5:
            final_bid = max(final_bid, highest_prev_bid * 0.9)
            final_bid = min(final_bid, MY_DAILY_SALARY * 0.85)
        else:
            final_bid = max(final_bid, highest_prev_bid + 5)
            final_bid = min(final_bid, MY_DAILY_SALARY * 0.99)
    elif highest_prev_bid > MY_DAILY_SALARY * 0.4:
        final_bid = max(final_bid, highest_prev_bid * 1.1)
        final_bid = min(final_bid, MY_DAILY_SALARY * 0.75)
    else:
        final_bid = max(final_bid, MY_DAILY_SALARY * 0.3)

    final_bid = min(final_bid, my_status['budget'])
    final_bid = min(final_bid, MY_DAILY_SALARY * 1.05)

    return max(0.1, final_bid)
